/* ===========================================================
   STYLES BELOW ARE COPIED VERBATIM FROM THE LIVE BLOG POST
   (/blog/best-time-book-painting-2026/). Do not alter them,
   they are what keeps every blog detail page consistent.
   =========================================================== */

/* root tokens, verbatim */
:root{
  --primary:#016edc; --primary-dark:#014284;
  --navy:#1c293f; --deep:#00334e; --accent:#ffa800;
  --ink:#1c293f; --muted:#5b6470;
  --light:#f0f0fa; --soft:#f5f5f5; --line:#e5e7eb; --white:#fff;
  --pill:60px; --r:16px; --r-lg:30px;
  --shadow:0 20px 50px #1c293f1a; --shadow-sm:0 8px 24px #1c293f14;
  --max:1200px;
  --font:"Fustat",-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
}
*{box-sizing:border-box}
html,body{margin:0}
body{font-family:var(--font);background:var(--white);color:var(--ink)}

/* shell, verbatim */
.wrap{max-width:var(--max);margin:0 auto;padding:0 24px}
.narrowx{max-width:820px}
.sec{padding:90px 0;position:relative}

/* article, verbatim */
.blog-post-content{margin:40px 0;line-height:1.8}
.blog-post-content h2{color:var(--navy);margin:32px 0 16px;font-size:1.75rem;font-weight:700;line-height:1.3}
.blog-post-content h3{color:var(--navy);margin:24px 0 12px;font-size:1.3rem;font-weight:600;line-height:1.4}
.blog-post-content p{color:var(--ink);margin-bottom:16px;font-size:1rem}
.blog-post-content ul,.blog-post-content ol{color:var(--ink);margin:16px 0 16px 24px}
.blog-post-content li{margin-bottom:10px;line-height:1.7}
.blog-post-content strong{font-weight:700}

/* headings + meta, verbatim */
.h1{font-family:var(--font);font-size:2.25rem;line-height:1.25;font-weight:800;letter-spacing:-.025em;color:var(--navy)}
.hh{color:var(--navy);letter-spacing:-.02em;margin-bottom:8px;font-family:Fustat,sans-serif;font-weight:800;line-height:1.16}
.post-header{border-bottom:none;margin-bottom:40px;padding-bottom:0}
.post-header h1{margin:0 0 12px;font-size:2rem;line-height:1.3}
.post-meta{color:var(--muted);font-size:.95rem;font-weight:400;display:block}
.post-meta span{display:inline}
.post-meta i{display:none}

/* hero, verbatim */
.blog-hero-container{border-radius:var(--r-lg);width:100%;height:auto;margin:32px 0 40px;overflow:hidden}
.blog-hero-image{object-fit:cover;width:100%;height:auto;display:block}

/* tables, verbatim (kept so future posts stay consistent) */
.blog-table{border-collapse:collapse;border:1px solid var(--line);width:100%;margin:24px 0;overflow:hidden}
.blog-table thead{background:#f8f9fa}
.blog-table th{text-align:left;color:var(--navy);border-bottom:2px solid var(--line);border-right:1px solid var(--line);background:#f8f9fa;padding:16px;font-weight:700}
.blog-table th:last-child{border-right:none}
.blog-table td{border-bottom:1px solid var(--line);border-right:1px solid var(--line);color:var(--ink);padding:16px}
.blog-table td:last-child{border-right:none}
.blog-table tbody tr:last-child td{border-bottom:none}
.blog-table tbody tr:hover{background:#fafbfc}
.blog-table a{color:#016edc;border-bottom:1px solid #016edc;font-weight:500;text-decoration:none}

/* links, verbatim */
.blog-link{color:#016edc;border-bottom:1px solid #016edc;font-weight:500;text-decoration:none;transition:opacity .3s}
.blog-link:hover{opacity:.7}
.blog-table-link{color:#016edc;border-bottom:1px solid #016edc;font-weight:500;text-decoration:none;transition:opacity .3s}
.blog-table-link:hover{opacity:.7}

/* the ONLY two responsive rules the live post has, verbatim */
@media (max-width:768px){
  .post-meta{gap:16px}
  .blog-table{font-size:.9rem}
  .blog-table th,.blog-table td{padding:12px}
}
@media (max-width:600px){
  .sec{padding:64px 0}
}

/* ===========================================================
   MOCKUP ONLY, NOT PART OF THE PRODUCTION STYLESHEET.
   Delete this block when the real hero image is dropped in.
   =========================================================== */
.imgph{background:var(--light);border:1px dashed #b9c3d6;color:var(--muted);
  display:flex;align-items:center;justify-content:center;text-align:center;
  padding:24px;min-height:360px;font-size:.9rem;line-height:1.6}

